using System;
class DestroyerAmmoPlacementChecks{static void Main(){var s=NavalShipDefinition.Novik;float q=s.Scale;for(int i=0;i<4;i++){var p=NavalCargoLayout.Position(s,i);if(Math.Abs(p.Z*q)>33)throw new Exception("Reserve too close to ends");foreach(var b in NavalDestroyerDesign.Equipment())if(b.Kind<=1&&Math.Abs(p.X*q-b.X)<1.5+b.W/2&&Math.Abs(p.Z*q-b.Z)<1.5+b.D/2)throw new Exception("Rack intersects machinery");}for(int g=0;g<s.GunCount;g++){float x=NavalReadyAmmoLayout.X(s,g)*q,z=NavalReadyAmmoLayout.Z(s,g)*q;foreach(var b in NavalDestroyerDesign.Equipment())if(b.Kind<=1&&Math.Abs(x-b.X)<.45+b.W/2&&Math.Abs(z-b.Z)<.35+b.D/2)throw new Exception("Ready locker intersects machinery");if(Math.Abs(x)+.45>4.5)throw new Exception("Side transit aisle obstructed");}Console.WriteLine("PASS: ammo away from extremities, no boiler/turbine overlaps, side transit aisles retained.");}}
